(function () {
  "use strict";
  const $=id=>document.getElementById(id), clone=x=>JSON.parse(JSON.stringify(x));
  const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const fmt=x=>x===null?'?':(Math.abs(x)<.00005?0:x).toFixed(4).replace('-','−');
  const exp=x=>x===0?'0':x.toExponential(2).replace('e-','e−');
  const rho=(p,s=[])=>`ρ<sub>${p.join('')}${s.length?'·'+s.join(','):''}</sub>`;
  const rhoSvg=(p,s=[])=>`ρ<tspan baseline-shift="sub" font-size="8">${p.join('')}${s.length?'·'+s.join(','):''}</tspan>`;
  const baseM=[[35,-25,null,10,-15],[-25,52,24,-31,null],[null,24,38,-2,null],[10,-31,-2,30,null],[-15,null,null,null,46]];
  const preset=baseM.map((row,i)=>row.map((v,j)=>v===null?null:v/Math.sqrt(baseM[i][i])/Math.sqrt(baseM[j][j])));
  preset.forEach((row,i)=>row[i]=1);
  const slides=[[1,-.586,null,.309,-.374],[-.586,1,.540,-.785,null],[null,.540,1,-.059,null],[.309,-.785,-.059,1,null],[-.374,null,null,null,1]];
  const state={matrix:clone(slides),base:clone(slides),reference:null,source:'slides',mode:'mask',pair:[0,1],step:0,free:{},response:null,revision:0,trace:0,completedTrees:false,referenceShown:false};
  const titles=['Prepare the incomplete matrix','Expand the graph into a vine','Choose the unspecified partials','Reconstruct, one calculation at a time','Inspect the result and compare'];
  function sourceLabel(){return {slides:'GIRO example · rounded inputs',preset:'Notebook example · full precision',generated:`Generated matrix · seed ${state.generationSeed}`,manual:'Manually supplied matrix',three:'3-variable example'}[state.source];}
  function renderControlNotes(){
    $('source-note').textContent={slides:'Rounded inputs from GIRO slide 3.',preset:'Full-precision notebook inputs; small rounding differences from GIRO.',generated:'Seeded positive definite matrix. Hide pairs to create an incomplete input.',manual:'Paste a 3–7 variable Pearson correlation matrix.',three:'Three variables: ρ₁₂ = ρ₂₃ = 0.5, with the 1–3 pair missing.'}[$('source').value];
    $('method-note').textContent=$('method').value==='vine'?'Set free partials in step 3. Zeros do not guarantee validity or optimality.':'Chordal graphs only. The optimum is independent of the vine representation.';
    $('strategy-note').textContent={greedy:'Prioritises known / strong edges.','c-vine':'Ordered roots; uses the variable order below.','d-vine':'Ordered path; uses the variable order below.'}[$('strategy').value];
  }
  function showStep(index){state.step=index;document.querySelectorAll('.stage').forEach((e,i)=>e.hidden=i!==index);document.querySelectorAll('[data-step]').forEach(e=>{e.classList.toggle('active',Number(e.dataset.step)===index);e.setAttribute('aria-current',Number(e.dataset.step)===index?'step':'false');});$('stage-title').textContent=titles[index];if(index===1)renderTrees();if(index===3)renderTrace();if(index===4)renderResult();}
  function error(message){$('lab-error').hidden=!message;$('lab-error').textContent=message||'';}
  function invalidate(){state.revision++;state.response=null;state.trace=0;state.completedTrees=false;state.referenceShown=false;$('lab-status').className='status';$('lab-status').textContent='Input changed · no result';$('export-general').disabled=true;$('truth-content').hidden=true;renderResult();renderEditor();}
  function payload(action){const partials=$('method').value==='vine'&&action==='complete'?(state.response?.plan?.freeEdges||[]).map(e=>({conditioned:e.conditioned,conditioning:e.conditioning,value:state.free[e.key]??0})):[];return {matrix:clone(state.matrix),method:$('method').value,strategy:$('strategy').value,order:$('order').value.split(',').map(v=>Number(v.trim())),partials,action};}
  async function request(action){const response=await fetch('/api/analyse',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload(action))});const output=await response.json();return output;}
  async function plan(){renderControlNotes();const ticket=++state.revision;error('');$('lab-status').textContent='Inspecting input…';try{const result=await request('plan');if(ticket!==state.revision)return;state.response=result;renderPlan();}catch(e){if(ticket!==state.revision)return;state.response=null;error('The local Python solver could not be reached. Run employer-demo/serve.py and open its localhost URL. '+e.message);$('lab-status').textContent='Local solver unavailable';$('lab-status').className='status invalid';}}
  async function complete(){if(!state.response?.plan){await plan();if(!state.response?.plan)return;}if($('method').value==='vine'&&state.response.plan.freeEdges.some(e=>!Number.isFinite(state.free[e.key]??0)||Math.abs(state.free[e.key]??0)>=1)){error('Every visible free partial must be finite and strictly between −1 and 1.');return;}const ticket=++state.revision;error('');$('lab-status').textContent='Completing and validating…';$('complete').disabled=true;$('complete-from-partials').disabled=true;try{const result=await request('complete');if(ticket!==state.revision)return;state.response=result;state.trace=0;state.referenceShown=false;renderPlan();showStep(3);}catch(e){if(ticket===state.revision){state.response=null;error('Local calculation failed: '+e.message);renderResult();}}finally{$('complete').disabled=false;$('complete-from-partials').disabled=false;}}
  function referenceUnchanged(){return !!state.reference&&state.matrix.every((row,i)=>row.every((v,j)=>v===null||Math.abs(v-state.reference[i][j])<1e-12));}
  function renderPlan(){renderControlNotes();const response=state.response,d=response?.inputDiagnostics;renderEditor();$('dataset-label').textContent=sourceLabel();if(!response){return;}$('input-feedback').className='input-feedback'+(!d?.observedGraphChordal||!response.ok?' warn':'');$('input-feedback').innerHTML=d?.structurallyValid?`<strong>${d.dimension} variables · ${d.observedPairs} supplied pairs · ${d.missingPairs} missing pairs.</strong> Observed graph: ${d.observedGraphChordal?'chordal':'nonchordal'}. ${esc(d.globalFeasibility.explanation)}${referenceUnchanged()?' A positive definite generating matrix is held out, so a completion exists; it is not supplied to the solver.':''}`:'The input has not passed structural validation.';
    if(response.error)error(response.error.type+': '+response.error.message);const result=response.result;
    $('lab-status').className='status'+(!response.ok?' invalid':result&&!result.diagnostics.max_entropy_certified?' assumed':'');
    $('lab-status').textContent=!response.ok?'No accepted completion':result?(result.diagnostics.max_entropy_certified?'Valid · max determinant certified':'Valid · explicit assumptions'):'Plan ready · not yet completed';
    $('export-general').disabled=!result;renderObserved();renderTrees();renderAssignments();renderResult();if(state.step===3)renderTrace();}
  function matrixTable(matrix,{observed=null,editable=false,labels=null,highlight=null,caption='Ordinary Pearson correlation'}={}){const n=matrix.length,format=n>=6?(v=>v===null?'?':(Math.abs(v)<.0005?0:v).toFixed(3).replace('-','−')):fmt,lab=labels||Array.from({length:n},(_,i)=>i+1);return `<table class="matrix ${editable?'editable':''} ${n>=6?'compact':''}"><caption>${esc(caption)}</caption><thead><tr><th scope="col">Risk</th>${lab.map(x=>`<th scope="col">R${x}</th>`).join('')}</tr></thead><tbody>`+matrix.map((row,i)=>`<tr><th scope="row">R${lab[i]}</th>`+row.map((v,j)=>{const selected=editable&&state.pair&&((i===state.pair[0]&&j===state.pair[1])||(j===state.pair[0]&&i===state.pair[1]));const source=v===null?'missing':i===j?'diagonal':observed&&!observed[i][j]?'inferred':'supplied';const hi=highlight&&((lab[i]===highlight[0]&&lab[j]===highlight[1])||(lab[j]===highlight[0]&&lab[i]===highlight[1]));return `<td class="${source}${selected?' selected-pair':''}${hi?' highlight':''}">${editable&&i!==j?`<button data-pair="${Math.min(i,j)},${Math.max(i,j)}" title="Risk ${lab[i]}–${lab[j]}: ${source}, ${v===null?'unknown':v}" aria-label="Risk ${lab[i]} and ${lab[j]}, ${source}, ${v===null?'unknown':v}">${format(v)}</button>`:`<span title="${source}: ${v}">${format(v)}${source==='inferred'?'<sup>*</sup>':''}</span>`}</td>`;}).join('')+'</tr>').join('')+'</tbody></table>';}
  function renderEditor(){const n=state.matrix.length;let pairs=0;state.matrix.forEach((row,i)=>row.forEach((v,j)=>{if(i<j&&v===null)pairs++;}));$('pair-count').textContent=`${pairs} missing / ${n*(n-1)/2} pairs`;$('mask-count').max=n*(n-1)/2-pairs;$('editable-matrix').innerHTML=matrixTable(state.matrix,{editable:true});$('editable-matrix').querySelectorAll('[data-pair]').forEach(button=>button.addEventListener('click',()=>{const [i,j]=button.dataset.pair.split(',').map(Number);state.pair=[i,j];if(state.mode==='mask'){const old=state.matrix[i][j];if(old!==null){state.stash??={};state.stash[`${i},${j}`]=old;state.matrix[i][j]=state.matrix[j][i]=null;}else{const restored=state.stash?.[`${i},${j}`]??state.base[i][j];if(restored===null){state.mode='edit';renderMode();renderEditor();return;}state.matrix[i][j]=state.matrix[j][i]=restored;}invalidate();plan();}else renderEditor();}));$('pair-editor').hidden=state.mode!=='edit';const [i,j]=state.pair||[0,1];$('pair-label').innerHTML=`Edit ${rho([i+1,j+1])} (both symmetric entries)`;$('pair-value').value=state.matrix[i]?.[j]??'';}
  function renderMode(){$('mask-mode').classList.toggle('selected',state.mode==='mask');$('edit-mode').classList.toggle('selected',state.mode==='edit');$('mask-mode').setAttribute('aria-pressed',String(state.mode==='mask'));$('edit-mode').setAttribute('aria-pressed',String(state.mode==='edit'));}
  function graphSvg(nodes,edges){const n=nodes.length,points=nodes.map((_,i)=>{const angle=2*Math.PI*i/n-Math.PI/2;return [160+112*Math.cos(angle),145+112*Math.sin(angle)];});let svg='<svg viewBox="0 0 320 290" role="img" aria-label="Observed risk graph">';edges.forEach(edge=>{const [i,j]=edge.pair.map(x=>x-1),[x1,y1]=points[i],[x2,y2]=points[j];svg+=`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${edge.value<0?'#a87151':'#4b7658'}" stroke-width="${1+Math.abs(edge.value)*2}"/><text x="${(x1+x2)/2}" y="${(y1+y2)/2-4}" text-anchor="middle" fill="#415e43" font-size="10" paint-order="stroke" stroke="#fff" stroke-width="4">${edge.value.toFixed(3)}</text>`;});points.forEach(([x,y],i)=>svg+=`<circle cx="${x}" cy="${y}" r="18" class="network-node"/><text x="${x}" y="${y}" class="network-text">R${nodes[i]}</text>`);return svg+'</svg>';}
  function renderObserved(){const graph=state.response?.graph;if(!graph){$('observed-graph').textContent='Input validation is required before a graph is shown.';return;}$('observed-graph').innerHTML=graphSvg(graph.nodes,graph.edges);}
  function treePositions(tree){
    const neighbours=new Map(tree.nodes.map(n=>[n.id,[]]));
    tree.edges.forEach(e=>{neighbours.get(e.u).push(e.v);neighbours.get(e.v).push(e.u);});
    const root=tree.nodes.slice().sort((a,b)=>neighbours.get(b.id).length-neighbours.get(a.id).length)[0].id;
    const depths=new Map(),children=new Map(),leafOrder=[];
    function walk(id,parent,depth){depths.set(id,depth);const list=neighbours.get(id).filter(x=>x!==parent);children.set(id,list);if(!list.length)leafOrder.push(id);list.forEach(x=>walk(x,id,depth+1));}
    walk(root,null,0);const maximum=Math.max(...depths.values(),1),positions=new Map();
    function place(id){const list=children.get(id);const x=list.length?list.map(place).reduce((a,b)=>a+b,0)/list.length:leafOrder.length===1?190:40+leafOrder.indexOf(id)*300/(leafOrder.length-1);positions.set(id,[x,25+depths.get(id)*120/maximum]);return x;}
    place(root);return positions;
  }
  function renderTrees(){const plan=state.response?.plan;if(!plan){$('vine-trees').innerHTML='<p class="stage-intro">A valid plan is needed before the vine can be expanded.</p>';return;}$('vine-policy').textContent=$('method').value==='max_entropy'?'The vine is a representation of dependence. The chordal maximum-determinant calculation is independent of this representation; changing the vine alone does not change that optimum.':'The selected vine determines where free partial-correlation assumptions are placed. Changing the structure or order can change the completion or make the chosen assumptions incompatible.';
    const actual=new Map((state.response.result?.edges||[]).map(e=>[e.key,e.partial_correlation]));let html=`<div class="tree-tools" style="grid-column:1/-1"><div class="segmented"><button id="trees-before" class="${state.completedTrees?'':'selected'}">Before assignment</button><button id="trees-after" class="${state.completedTrees?'selected':''}" ${!state.response.result?'disabled':''}>Completed vine</button></div></div>`;
    plan.trees.forEach(tree=>{const coords=treePositions(tree);let svg='<svg viewBox="0 0 380 170" role="img" aria-label="Vine tree '+tree.level+'">';tree.edges.forEach(edge=>{const [x1,y1]=coords.get(edge.u),[x2,y2]=coords.get(edge.v);const value=state.completedTrees?actual.get(edge.key):edge.partial_from_observations;const unknown=value===null||value===undefined;const text=`${rhoSvg(edge.conditioned,edge.conditioning)} = ${unknown?(!edge.observed_pair?'?':'later'):Math.abs(value)<1e-10?'0':value.toFixed(3)}`;svg+=`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" class="tree-edge${unknown&&!edge.observed_pair?' free':''}"/><text x="${(x1+x2)/2+(Math.abs(x1-x2)<1?28:0)}" y="${(y1+y2)/2+(Math.abs(x1-x2)<1?4:-9)}" text-anchor="${Math.abs(x1-x2)<1?'start':'middle'}" class="tree-label tree-edge-label" paint-order="stroke" stroke="#fbfcf7" stroke-width="5" style="text-anchor:${Math.abs(x1-x2)<1?'start':'middle'};fill:${unknown?(!edge.observed_pair?'#a46b28':'#6d7967'):'#39573d'}">${text}</text>`;});tree.nodes.forEach(node=>{const [x,y]=coords.get(node.id);svg+=`<circle cx="${x}" cy="${y}" r="21" class="tree-node"/><text x="${x}" y="${y+3}" class="tree-label" style="font-size:${node.variables.length>4?8:10}px">${node.variables.join(',')}</text>`;});html+=`<div class="tree-card"><h4>Tree T${tree.level}</h4>${svg}</svg><p>${tree.level===1?'Ordinary correlations':'Partial correlations; node labels show their variable sets'}</p></div>`;});$('vine-trees').innerHTML=html;$('trees-before').onclick=()=>{state.completedTrees=false;renderTrees();};$('trees-after').onclick=()=>{state.completedTrees=true;renderTrees();};}
  function renderAssignments(){const plan=state.response?.plan;if(!plan){$('assignments').innerHTML='<p>A valid vine plan is needed.</p>';return;}const vine=$('method').value==='vine';$('assignment-explanation').textContent=vine?'Assign a value in (−1,1) to each free vine edge. The visible initial values of zero are modelling assumptions. They are sent explicitly; the solver does not invent unspecified values. Some choices can conflict with the known correlations.':'Maximum determinant uses the supported chordal calculation. Free partial correlations below are computed from the optimum, rather than fixed to zero on an arbitrary vine. Choose the explicit-vine objective to supply your own values.';const actual=new Map((state.response.result?.edges||[]).map(e=>[e.key,e.partial_correlation]));$('assignments').innerHTML='<table class="assignment-table"><thead><tr><th>Tree</th><th>Free edge</th><th>Value</th><th>Meaning</th></tr></thead><tbody>'+plan.freeEdges.map(edge=>{state.free[edge.key]??=0;return `<tr><td>T${edge.tree}</td><td>${rho(edge.conditioned,edge.conditioning)}</td><td>${vine?`<input data-partial="${esc(edge.key)}" aria-label="Partial ${esc(edge.key)}" type="number" min="-0.999999" max="0.999999" step="0.05" value="${state.free[edge.key]}">`:(actual.has(edge.key)?actual.get(edge.key).toFixed(6):'Computed on completion')}</td><td>${vine?'<span class="free-tag">Explicit assumption</span>':'Derived, not preassigned'}${edge.conditioning.length?'':'<small>Ordinary correlation</small>'}</td></tr>`;}).join('')+'</tbody></table>';$('assignment-summary').textContent=`${plan.freeEdges.length} free edge${plan.freeEdges.length===1?'':'s'} on this vine.`;$('assignments').querySelectorAll('[data-partial]').forEach(input=>input.addEventListener('input',()=>{const value=input.valueAsNumber;state.free[input.dataset.partial]=value;state.revision++;if(state.response){state.response.result=null;state.response.trace=[];}if(!Number.isFinite(value)||Math.abs(value)>=1){$('lab-status').textContent='Invalid partial · no result';$('lab-status').className='status invalid';renderResult();error('Free partial correlations must be finite and strictly between −1 and 1.');return;}$('lab-status').textContent='Assumptions changed · no result';$('export-general').disabled=true;error('');renderResult();}));}
  function renderTrace(){const entries=(state.response?.trace||[]).filter(e=>['vine_edge','clique_forest','clique_contribution','separator_contribution','precision_inverse'].includes(e.stage));if(!entries.length){$('trace-position').textContent='No accepted reconstruction yet';$('trace-content').innerHTML='<p class="stage-intro">Run the completion after choosing your strategy and assumptions. If a calculation fails, its available steps and error remain visible.</p>';$('trace-prev').disabled=$('trace-next').disabled=true;return;}state.trace=Math.min(state.trace,entries.length-1);const e=entries[state.trace];$('trace-position').textContent=`Calculation ${state.trace+1} of ${entries.length}`;$('trace-prev').disabled=state.trace===0;$('trace-next').disabled=state.trace===entries.length-1;$('reconstruction-note').textContent=$('method').value==='vine'?'Reconstruct in tree order. Known ordinary correlations stay fixed. Free correlations are recovered from their chosen partial correlation and the lower-order entries already available.':'Assemble the precision matrix K from the specified cliques and separators, then invert it. This is the actual chordal maximum-determinant calculation; it does not assume arbitrary greedy free partials are zero.';let html='<div class="trace-card">';if(e.stage==='vine_edge'){html+=`<h4>T${e.level}: ${rho(e.pair,e.conditioning)}</h4><p>${e.source==='observed'?'The ordinary correlation is observed and remains fixed. Its partial correlation is calculated.':'A missing ordinary correlation is reconstructed using the explicit partial assumption.'}</p>${e.failed?`<div class="lab-error">${esc(e.message)}</div>`:`<div class="trace-formula">R<sub>${e.pair.join('')}</sub> = ${e.base.toFixed(6)} + ${e.partialValue.toFixed(6)} × ${e.multiplier.toFixed(6)} = <strong>${e.ordinaryCorrelation.toFixed(6)}</strong></div>`}<div class="trace-matrices"><div><h5>Before this edge</h5>${matrixTable(e.before)}</div><div><h5>After this edge</h5>${matrixTable(e.after,{highlight:e.pair})}</div></div>`;}else if(e.stage==='clique_forest'){html+=`<h4>Identify cliques and their separators</h4><p>${esc(e.message)}</p><div class="trace-formula">K = Σ embed(R<sub>CC</sub><sup>−1</sup>) − Σ embed(R<sub>SS</sub><sup>−1</sup>)</div><p>Cliques: ${e.cliques.map(x=>'{'+x.join(',')+'}').join(' · ')}<br>Separators: ${e.separators.map(x=>'{'+x.join(',')+'}').join(' · ')||'none'}</p>`;}else if(e.stage==='precision_inverse'){html+=`<h4>Invert K to recover R</h4><p>${esc(e.message)}</p><div class="trace-matrices"><div><h5>Assembled precision K</h5>${matrixTable(e.precision,{caption:'Precision matrix (inverse correlation)'})}</div><div><h5>Completed ordinary correlation R</h5>${matrixTable(e.after)}</div></div>`;}else{html+=`<h4>${e.sign===1?'Add clique':'Subtract separator'} {${e.labels.join(',')}}</h4><p>Invert this fully specified block and embed its contribution into K. An intermediate precision sum is not yet a completed correlation matrix.</p><div class="trace-matrices"><div><h5>Specified correlation block</h5>${matrixTable(e.block,{labels:e.labels})}</div><div><h5>Precision sum after this contribution</h5>${matrixTable(e.precisionAfter,{caption:'Intermediate precision sum'})}</div></div>`;}$('trace-content').innerHTML=html+'</div>';}
  function renderResult(){const result=state.response?.result;const div=$('general-result');$('ground-truth').hidden=!state.reference||!result;$('truth-content').hidden=!state.referenceShown;$('export-general').disabled=!result;if(!result){div.innerHTML='<p class="stage-intro">There is no accepted result for the current input and assumptions. Run completion to see a fresh matrix and validation. A previous certificate is never reused.</p>';return;}const d=result.diagnostics,observed=state.matrix.map(row=>row.map(v=>v!==null));div.innerHTML=matrixTable(result.correlation,{observed})+`<div class="matrix-legend"><span><i class="given-key"></i> Supplied</span><span><i class="inferred-key"></i> Inferred *</span></div><div class="diagnostics"><div class="metric"><span>Minimum eigenvalue of R</span><strong>${d.minimum_eigenvalue_correlation.toFixed(6)}</strong><small>Must exceed 1e−10</small></div><div class="metric"><span>Supplied-entry error</span><strong>${exp(d.maximum_observed_error_correlation)}</strong><small>Supplied values preserved</small></div><div class="metric"><span>log det(R)</span><strong>${d.log_determinant_correlation.toFixed(6)}</strong><small>Compare under identical constraints</small></div><div class="metric"><span>Free precision residual</span><strong>${exp(d.free_precision_max_abs)}</strong><small>${d.max_entropy_certified?'≤1e−8 · max determinant certified':'No maxdet certificate for original constraints'}</small></div></div><p class="general-result-note">${d.missing_pairs_completed} pairs completed. ${d.max_entropy_certified?'The numerical certificate supports the maximum-determinant result under the original supplied-entry constraints.':'The result is positive definite and preserves supplied values; your partial assumptions solve a different modelling problem.'} The Gaussian entropy interpretation additionally requires a Gaussian model and fixed variances.</p>`;if(state.referenceShown)renderTruth();}
  function renderTruth(){const result=state.response?.result;if(!result||!state.reference)return;const pairs=[];for(let i=0;i<state.matrix.length;i++)for(let j=i+1;j<state.matrix.length;j++)if(state.matrix[i][j]===null)pairs.push([i,j]);const errors=pairs.map(([i,j])=>result.correlation[i][j]-state.reference[i][j]);const rmse=errors.length?Math.sqrt(errors.reduce((sum,x)=>sum+x*x,0)/errors.length):0,max=errors.length?Math.max(...errors.map(Math.abs)):0;$('truth-content').hidden=false;$('truth-content').innerHTML=`<div class="comparison-metrics">Held-out pairs: ${pairs.length} · RMSE: <strong>${rmse.toFixed(6)}</strong> · Maximum absolute difference: <strong>${max.toFixed(6)}</strong></div><p class="recovery-note">${referenceUnchanged()?'The generating matrix is a valid reference completion, but the selected objective need not recover it.':'Known entries have been edited. This is the original generating reference before those edits, so it is no longer necessarily compatible with the current constraints.'} Hidden values were never included in a solver request.</p><div class="truth-grid"><div><h5>Held-out generating reference</h5>${matrixTable(state.reference)}</div><div><h5>Current completion minus reference</h5>${matrixTable(result.correlation.map((row,i)=>row.map((v,j)=>v-state.reference[i][j])),{caption:'Differences in ordinary correlation'})}</div></div>`;}
  function load(matrix,source,reference=null){if(!Array.isArray(matrix)||matrix.length<3||matrix.length>7||matrix.some(row=>!Array.isArray(row)||row.length!==matrix.length))throw new Error('Use a square 3–7 variable matrix.');matrix.forEach((row,i)=>row.forEach((v,j)=>{if(v!==null&&(typeof v!=='number'||!Number.isFinite(v)))throw new Error('Entries must be finite numbers or null.');if(i===j&&Math.abs(v-1)>1e-10)throw new Error('Every diagonal entry must be 1.');if((v===null)!==(matrix[j][i]===null)||(v!==null&&Math.abs(v-matrix[j][i])>1e-10))throw new Error('The matrix and its missing entries must be symmetric.');}));state.matrix=clone(matrix);state.base=clone(matrix);state.reference=reference?clone(reference):null;state.source=source;state.generationSeed=source==='generated'?$('seed').valueAsNumber:null;state.free={};state.stash={};state.pair=[0,1];$('order').value=matrix.map((_,i)=>i+1).join(',');$('source').value=source;$('generation').hidden=source!=='generated';$('manual').hidden=source!=='manual';$('dataset-label').textContent=sourceLabel();invalidate();showStep(0);plan();}
  function generate(){try{const matrix=MatrixInputs.generate(Number($('dimension').value),$('seed').valueAsNumber);load(matrix,'generated',matrix);}catch(e){error(e.message);}}
  $('source').onchange=()=>{const source=$('source').value;renderControlNotes();$('generation').hidden=source!=='generated';$('manual').hidden=source!=='manual';if(source==='slides'){$('method').value='vine';$('strategy').value='greedy';load(slides,'slides');}else if(source==='generated')generate();else if(source==='preset')load(preset,'preset');else if(source==='three')load([[1,.5,null],[.5,1,.5],[null,.5,1]],'three');else{state.source='manual';$('matrix-json').value=JSON.stringify(state.matrix);$('dataset-label').textContent='Manual matrix editor · apply or edit below';}};
  $('generate').onclick=generate;$('apply-matrix').onclick=()=>{try{const matrix=JSON.parse($('matrix-json').value.replace(/\?/g,'null'));if(!Array.isArray(matrix)||matrix.length<3||matrix.length>7||matrix.some(row=>!Array.isArray(row)||row.length!==matrix.length))throw new Error('Use a square JSON matrix with 3–7 variables.');load(matrix,'manual');}catch(e){invalidate();$('lab-status').textContent='Manual input rejected · no result';$('input-feedback').className='input-feedback warn';$('input-feedback').textContent='Rejected input was not applied. The previous matrix remains available for correction; it has no accepted result in this state.';error('Manual input not applied: '+e.message);}};
  $('random-mask').onclick=()=>{try{const pairs=MatrixInputs.choosePairs(state.matrix,$('mask-count').valueAsNumber,$('mask-seed').valueAsNumber);state.stash??={};pairs.forEach(([i,j])=>{state.stash[`${i},${j}`]=state.matrix[i][j];state.matrix[i][j]=state.matrix[j][i]=null;});invalidate();showStep(0);plan();}catch(e){error(e.message);}};
  $('restore-input').onclick=()=>{state.matrix=clone(state.base);state.stash={};state.free={};invalidate();plan();};$('reset-lab').onclick=()=>{$('method').value='vine';$('strategy').value='greedy';load(slides,'slides');};
  $('mask-mode').onclick=()=>{state.mode='mask';renderMode();renderEditor();};$('edit-mode').onclick=()=>{state.mode='edit';renderMode();renderEditor();};
  $('set-pair').onclick=()=>{const value=$('pair-value').valueAsNumber;if(!Number.isFinite(value)||Math.abs(value)>=1){error('An off-diagonal correlation must be finite and strictly between −1 and 1.');return;}const [i,j]=state.pair;state.matrix[i][j]=state.matrix[j][i]=value;invalidate();plan();};$('hide-pair').onclick=()=>{const [i,j]=state.pair;state.stash??={};if(state.matrix[i][j]!==null)state.stash[`${i},${j}`]=state.matrix[i][j];state.matrix[i][j]=state.matrix[j][i]=null;invalidate();plan();};
  ['method','strategy','order'].forEach(id=>$(id).onchange=()=>{state.free={};invalidate();plan();});
  document.querySelectorAll('[data-step]').forEach(e=>e.onclick=()=>showStep(Number(e.dataset.step)));document.querySelectorAll('[data-next]').forEach(e=>e.onclick=()=>showStep(Number(e.dataset.next)));$('complete').onclick=complete;$('complete-from-partials').onclick=complete;$('trace-prev').onclick=()=>{state.trace=Math.max(0,state.trace-1);renderTrace();};$('trace-next').onclick=()=>{state.trace++;renderTrace();};$('reveal-truth').onclick=()=>{state.referenceShown=!state.referenceShown;$('reveal-truth').textContent=state.referenceShown?'Hide reference':'Reveal hidden reference & compare';$('truth-content').hidden=!state.referenceShown;if(state.referenceShown)renderTruth();};
  $('export-general').onclick=()=>{if(!state.response?.result)return;const data={problem:payload('complete'),result:state.response.result,trace:state.response.trace,scale:'Ordinary Pearson correlation',note:'Illustrative local calculation. Hidden generating reference excluded.'};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='vine-matrix-experiment.json';a.click();URL.revokeObjectURL(url);};
  $('dataset-label').textContent=sourceLabel();renderEditor();plan();
})();
